import 'package:flutter/material.dart';
import '../services/api_service.dart';
import '../services/auth_service.dart';

class ListScreen extends StatefulWidget { final AuthService auth; final String endpoint; final String title; const ListScreen({super.key, required this.auth, required this.endpoint, required this.title}); @override State<ListScreen> createState() => _ListScreenState(); }
class _ListScreenState extends State<ListScreen> { final _search = TextEditingController(); List<dynamic> _items = []; String? _error; bool _busy = false; @override void initState() { super.initState(); _load(); } @override void dispose() { _search.dispose(); super.dispose(); }
 Future<void> _load() async { setState(() => _busy = true); try { final separator = widget.endpoint.contains('?') ? '&' : '?'; final suffix = _search.text.trim().isEmpty ? '' : '${separator}buscar=${Uri.encodeQueryComponent(_search.text.trim())}'; final result = await widget.auth.api.get('/${widget.endpoint}$suffix'); if (mounted) setState(() { _items = result['data'] as List<dynamic>; _error = null; }); } on ApiException catch (e) { if (mounted) setState(() => _error = e.message); } finally { if (mounted) setState(() => _busy = false); } }
 Future<void> _show(Map<String, dynamic> item) async { try { final endpoint = widget.endpoint.split('?').first; final result = await widget.auth.api.get('/$endpoint/${item['id']}'); final data = Map<String, dynamic>.from(result['data'] as Map); if (!mounted) return; await showDialog<void>(context: context, builder: (_) => AlertDialog(title: Text('Detalle de ${widget.title}'), content: SizedBox(width: 420, child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: data.entries.where((entry) => entry.value is! Map && entry.value is! List).map((entry) => ListTile(dense: true, contentPadding: EdgeInsets.zero, title: Text(entry.key), trailing: Text(entry.value?.toString() ?? '-'))).toList()))), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cerrar'))])); } on ApiException catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message))); } }
 @override Widget build(BuildContext context) => Column(children: [Padding(padding: const EdgeInsets.all(12), child: Row(children: [Expanded(child: TextField(controller: _search, onSubmitted: (_) => _load(), decoration: InputDecoration(labelText: 'Buscar ${widget.title.toLowerCase()}', suffixIcon: IconButton(onPressed: _load, icon: const Icon(Icons.search))))), const SizedBox(width: 8), IconButton(onPressed: _busy ? null : _load, icon: const Icon(Icons.refresh))])), Expanded(child: _busy && _items.isEmpty ? const Center(child: CircularProgressIndicator()) : _error != null ? Center(child: Text(_error!)) : _items.isEmpty ? const Center(child: Text('No hay registros.')) : RefreshIndicator(onRefresh: _load, child: ListView.separated(itemCount: _items.length, separatorBuilder: (_, __) => const Divider(height: 1), itemBuilder: (_, index) { final item = Map<String, dynamic>.from(_items[index] as Map); return ListTile(title: Text(_title(item)), subtitle: Text(_subtitle(item)), trailing: const Icon(Icons.chevron_right), onTap: () => _show(item)); }))) ]);
 String _title(Map<String, dynamic> x) => (x['codigo'] ?? x['placa'] ?? x['nombre'] ?? x['username'] ?? x['id']).toString(); String _subtitle(Map<String, dynamic> x) => [x['zona'], x['marca'], x['modelo'], x['estado'], x['nombre'] != null ? x['apellido'] : null, x['role'] is Map ? x['role']['role'] : x['role']].whereType<Object>().join(' · ');
}
